/* ---------- gisements : taille et stock ----------
   La taille découle de la graine de la case ; garantie de spawn : les 3
   gisements les plus proches de la Source font UN petit, UN moyen, UN grand
   (le petit d'abord — c'est lui que le tutoriel fait récolter). */
const CRX_Q = 120; // stock de base (💠) — small 1x, medium 2x, big 3x
const CRX_V = 0.6; // vitesse d'extraction de base (💠/s) — 1x/2x/3x
const crysSzOver = (() => {
  const list = [];
  for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
    if (x === SRC.x && y === SRC.y) continue;
    // carte BRUTE (cache), pas tileAt() : un gisement épuisé (clearedSet)
    // doit garder sa place dans l'ordre, sinon les tailles des autres
    // gisements changeraient d'une session à l'autre
    tileAt(x, y);
    if (tcache.get(x + "," + y).kind === "crystal")
      list.push([x, y, Math.abs(x - SRC.x) + Math.abs(y - SRC.y)]);
  }
  list.sort((a, b) => a[2] - b[2]);
  const m = new Map();
  [0, 1, 2].forEach((sz, i) => { if (list[i]) m.set(list[i][0] + "," + list[i][1], sz); });
  return m;
})();
// reprise v8 : un gisement qui avait été « déblayé » redevient un gisement
// mort — il se reformera comme les autres (jamais définitivement perdu)
(function () {
  if (!S.cleared || !S.cleared.length) return;
  const rest = [];
  for (const k of S.cleared) {
    const [cx, cy] = k.split(",").map(Number);
    tileAt(cx, cy); // prime le cache
    const raw = tcache.get(k);
    if (raw && raw.kind === "crystal") S.crxDead[k] = Date.now();
    else rest.push(k);
  }
  if (rest.length !== S.cleared.length) { S.cleared = rest; clearedSet = new Set(rest); }
})();
function crysSize(x, y) {
  const t = crxTailles[x + "," + y];
  if (t != null) return t; // gisements du plateau de départ : taille choisie
  const o = crysSzOver.get(x + "," + y);
  if (o != null) return o;
  const u = (tileAt(x, y).j * 29) % 1;
  return u < 0.5 ? 0 : (u < 0.85 ? 1 : 2);
}
function crysMax(x, y) { return CRX_Q * (crysSize(x, y) + 1); }
function crysStock(x, y) {
  const v = S.crx[x + "," + y];
  return v == null ? crysMax(x, y) : v;
}
/* Débit de CRISTAUX 💎 des drones (seuls les gisements encore fournis comptent).
   Depuis le 15/08, miner ne rapporte plus des matériaux mais des cristaux : une
   monnaie à part, dont c'est aujourd'hui l'UNIQUE source. L'ancienne mise en
   pause « entrepôt plein » a disparu avec elle — elle gelait l'extraction dès
   que les matériaux plafonnaient (et, sur le plateau où la trésorerie locale est
   gonflée, elle la gelait TOUT LE TEMPS : compteur figé, gisement jamais épuisé,
   drone jamais rappelé — les symptômes remontés par le propriétaire). */
function cryRate() {
  return CRX_V * S.units.reduce((a, u) => a + (u.t === "recolteur" &&
    tileAt(u.x, u.y).kind === "crystal" && crysStock(u.x, u.y) > 0
    ? crysSize(u.x, u.y) + 1 : 0), 0);
}
// épuisement d'un gisement : il DESPAWN (case sable) et respawne plus tard
const CRX_RESPAWN = 5 * 60 * 1000; // 5 min avant la reformation du gisement
function crysDeplete(x, y, i) {
  const k = x + "," + y;
  delete S.crx[k];
  S.crxDead[k] = Date.now();
  S.units.splice(i, 1); S.dr = (S.dr || 0) + 1;
  toast("✨ <b>Gisement épuisé</b> — le drone ouvrier rentre en soute (" + S.dr + " dispo).", true);
  save();
}
// Un drone ouvrier n'a de sens que sur un gisement : dès que le sien
// disparaît (épuisé, ou carte mise à jour), il rentre en soute — jamais de
// drone en vol stationnaire au-dessus du sable ou d'un bâtiment.
function dronesOrphelins() {
  let n = 0;
  for (let i = S.units.length - 1; i >= 0; i--) {
    const u = S.units[i];
    if (u.t !== "recolteur" || tileAt(u.x, u.y).kind === "crystal") continue;
    S.units.splice(i, 1); S.dr = (S.dr || 0) + 1; n++;
  }
  if (n) {
    netDirty = true;
    toast("🛸 " + n + (n > 1 ? " drones ouvriers sont rentrés" : " drone ouvrier est rentré") +
      " en soute — plus de gisement sous eux.");
    save();
  }
  return n;
}
// reformation : jamais sous un bâtiment ou une unité (on attend que ça se libère)
let crxRespawnAcc = 0;
function tickRespawn(dt) {
  crxRespawnAcc += dt;
  if (crxRespawnAcc < 1) return;
  crxRespawnAcc = 0;
  dronesOrphelins();
  const now = Date.now();
  for (const k of Object.keys(S.crxDead)) {
    if (now - S.crxDead[k] < CRX_RESPAWN) continue;
    const [cx, cy] = k.split(",").map(Number);
    if (!fpLibre(cx, cy, [0.27, 0.40, 0.53][crysSize(cx, cy)])) {
      S.crxDead[k] = now - CRX_RESPAWN + 60000; // occupé : on réessaie dans 1 min
      continue;
    }
    delete S.crxDead[k];
    toast("✨ Un <b>gisement de cristaux</b> s'est reformé.", true);
    save();
  }
}
// extraction réelle : chaque drone vide son gisement à sa vitesse
function tickExtraction(dt) {
  for (let i = S.units.length - 1; i >= 0; i--) {
    const u = S.units[i];
    if (u.t !== "recolteur" || tileAt(u.x, u.y).kind !== "crystal") continue;
    const st = crysStock(u.x, u.y);
    if (st <= 0) continue;
    S.crx[u.x + "," + u.y] = st - Math.min(st, CRX_V * (crysSize(u.x, u.y) + 1) * dt);
    if (S.crx[u.x + "," + u.y] <= 0.01) crysDeplete(u.x, u.y, i);
  }
}
function zoneImg(Z) {
  const px = Z.w * TILE.world * cam.z * DPR;
  const w = [256, 512, Z.img.width].find((v) => v >= px) || Z.img.width;
  let c = Z.mips[w];
  if (!c) {
    c = Z.mips[w] = document.createElement("canvas");
    c.width = w; c.height = Math.round(w * Z.img.height / Z.img.width);
    c.getContext("2d").drawImage(Z.img, 0, 0, c.width, c.height);
  }
  return c;
}
function plateauDiamond() { // losange EXACT du territoire (fermé)
  const z = cam.z;
  const n = w2s(bmin(), bmin()), e = w2s(bmax(), bmin());
  const s = w2s(bmax(), bmax()), o = w2s(bmin(), bmax());
  ctx.beginPath();
  ctx.moveTo(n.x, n.y - TH / 2 * z);
  ctx.lineTo(e.x + TW / 2 * z, e.y);
  ctx.lineTo(s.x, s.y + TH / 2 * z);
  ctx.lineTo(o.x - TW / 2 * z, o.y);
  ctx.closePath();
}
// Le massif est un rendu iso vu du même angle que le plateau : on ne le fait
// donc JAMAIS pivoter (les pics pointeraient vers le bas). aplat < 1 le couche
// un peu pour qu'il tienne en bande sans écraser le relief.
// libre : la zone n'est pas rognée par le bord du plateau (le relief a le
// droit de mordre sur le vide — retour propriétaire pour la montagne)
function drawZone(Z, cx, cy, dx, dy, ancre, aplat, libre) {
  if (!Z.ok) return;
  const p = w2s(cx + (dx || 0), cy + (dy || 0)), z = cam.z;
  const sw = Z.w * TW * z, sh = sw * Z.hw * (aplat == null ? 1 : aplat);
  const oy = sh * (ancre == null ? 0.5 : ancre);
  ctx.save();
  if (!libre) { plateauDiamond(); ctx.clip(); }
  ctx.drawImage(zoneImg(Z), p.x - sw / 2, p.y - oy, sw, sh);
  ctx.restore();
}
function drawDunes() {
  if (!DUNE.ok) return;
  const p = w2s(DUNE_CX - 0.33, DUNE_CY + 0.33), z = cam.z; // écarté vers le bord
  const sw = DUNE.w * TW * z, sh = sw * DUNE.hw;
  ctx.save();
  plateauDiamond(); ctx.clip(); // losange exact : rien ne sort du plateau
  ctx.drawImage(duneImg(), p.x - sw / 2, p.y - sh * 0.5, sw, sh);
  ctx.restore();
}
function drawLac() {
  if (!LAC.ok) return;
  const p = w2s(LAC_CX + 0.33, LAC_CY - 0.33), z = cam.z; // écarté vers le bord
  const sw = LAC.w * TW * z, sh = sw * LAC.hw;
  ctx.save();
  plateauClipPath(); ctx.clip();
  ctx.drawImage(lacImg(), p.x - sw / 2, p.y - sh * 0.52, sw, sh);
  ctx.restore();
}
const TILE = { ok: false, world: TW, mips: {} }; // 1 répétition ≈ 1 case ; mips pour un grain net à tout zoom
(function () {
  const img = new Image();
  img.onload = () => { TILE.img = img; TILE.ok = true; fitCam(); };
  img.src = "data:image/webp;base64,";
})();
function zBounds() { return { lo: W <= 760 ? 0.9 : 1.6, hi: 8.1 }; }
function clampCam() { // le centre de l'écran reste proche du territoire (jamais perdu dans le vide)
  if (view !== "col") return;
  const m = ((bmax() - bmin()) / 2 + 4) * TW;
  const cx0 = (SRC.x - SRC.y) * TW / 2, cy0 = (SRC.x + SRC.y) * TH / 2;
  const wx = (W / 2 - cam.x) / cam.z, wy = (H / 2 - cam.y) / cam.z;
  cam.x = W / 2 - Math.max(cx0 - m, Math.min(cx0 + m, wx)) * cam.z;
  cam.y = H / 2 - Math.max(cy0 - m * TH / TW, Math.min(cy0 + m * TH / TW, wy)) * cam.z;
}
function tilePattern() {
  // niveau de mip : la plus petite version ≥ la taille affichée (net sans bouillie)
  const px = TILE.world * cam.z * DPR;
  const size = [128, 256, 512, TILE.img.width].find((v) => v >= px) || TILE.img.width;
  let mp = TILE.mips[size];
  if (!mp) {
    const c = document.createElement("canvas");
    c.width = c.height = size;
    c.getContext("2d").drawImage(TILE.img, 0, 0, size, size);
    mp = TILE.mips[size] = { pat: ctx.createPattern(c, "repeat"), size };
  }
  return mp;
}
const WALL = { ok: false }; // fond : la planète vue d'orbite (wallpaper du propriétaire)
(function () {
  const img = new Image();
  img.onload = () => { WALL.img = img; WALL.ok = true; };
  img.src = "data:image/webp;base64,";
})();
function drawWallpaper() {
  if (!WALL.ok) { ctx.fillStyle = "#060913"; ctx.fillRect(0, 0, W, H); return; }
  // statique, en « cover » exact : à 16:9 l'image est visible en entier et remplit l'écran
  const iw = WALL.img.width, ih = WALL.img.height;
  const sc = Math.max(W / iw, H / ih);
  const dw = iw * sc, dh = ih * sc;
  ctx.drawImage(WALL.img, (W - dw) / 2, (H - dh) / 2, dw, dh);
  ctx.fillStyle = "rgba(4, 6, 15, .42)"; // voile : le plateau reste la vedette
  ctx.fillRect(0, 0, W, H);
}
function drawTerrainTex() {
  if (!TILE.ok) return;
  const mp = tilePattern();
  const k = cam.z * TILE.world / mp.size;
  // clip au losange du territoire : le monde s'arrête où s'arrête le déblocage
  const T = w2s(bmin() - 0.5, bmin() - 0.5), R = w2s(bmax() + 0.5, bmin() - 0.5);
  const B = w2s(bmax() + 0.5, bmax() + 0.5), L = w2s(bmin() - 0.5, bmax() + 0.5);
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(T.x, T.y); ctx.lineTo(R.x, R.y); ctx.lineTo(B.x, B.y); ctx.lineTo(L.x, L.y);
  ctx.closePath();
  ctx.clip();
  ctx.setTransform(DPR * k, 0, 0, DPR * k, DPR * cam.x, DPR * cam.y);
  ctx.fillStyle = mp.pat;
  ctx.fillRect(-cam.x / k, -cam.y / k, W / k, H / k);
  // étalonnage : accorder le plateau à l'ambiance du fond (clip toujours actif)
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  ctx.globalCompositeOperation = "saturation";
  ctx.fillStyle = "rgba(128, 128, 128, 0.20)"; // désaturation allégée : le sol rejoint le ton des assets
  ctx.fillRect(0, 0, W, H);
  ctx.globalCompositeOperation = "multiply";
  ctx.fillStyle = "rgb(253, 226, 180)"; // ton accordé au sable des assets (retour 2026-08-14)
  ctx.fillRect(0, 0, W, H);
  const lg = ctx.createLinearGradient(W, 0, W * 0.25, H);
  lg.addColorStop(0, "rgba(255, 200, 130, .30)"); // lumière du levant (haut droit)
  lg.addColorStop(0.5, "rgba(255, 200, 130, .08)");
  lg.addColorStop(1, "rgba(30, 40, 70, .16)"); // ombre bleutée à l'opposé
  ctx.globalCompositeOperation = "overlay";
  ctx.fillStyle = lg;
  ctx.fillRect(0, 0, W, H);
  ctx.globalCompositeOperation = "source-over";
  ctx.restore();
}
